using System;using System.Linq;using System.Web.UI.WebControls;using ForteMove.Models.Operations;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Driver{public partial class ReportDefect:DriverPage{private long Id{get{long x;return long.TryParse(Request.QueryString["id"],out x)?x:0;}}protected void Page_Load(object s,EventArgs e){if(!IsPostBack){BindOptions();LoadContext();}}private void BindOptions(){ddlCategory.Items.Add(new ListItem("Select category",string.Empty));foreach(DefectCategory x in Enum.GetValues(typeof(DefectCategory)))ddlCategory.Items.Add(new ListItem(Label(x.ToString()),x.ToString()));ddlSeverity.Items.Add(new ListItem("Select severity",string.Empty));foreach(DefectSeverity x in Enum.GetValues(typeof(DefectSeverity)))ddlSeverity.Items.Add(new ListItem(x.ToString(),x.ToString()));}private void LoadContext(){var d=ServiceFactory.CreateDriverOperationsService().GetTripDetails(CurrentPrincipalContext.UserAccountId,Id);if(d==null){Response.Redirect(ResolveUrl("~/Driver/Today.aspx"),true);return;}litContext.Text=Server.HtmlEncode(d.TripCode+" · Bus "+d.FleetNumber);hidTripRv.Value=Convert.ToBase64String(d.TripRowVersion);hidAssignmentRv.Value=Convert.ToBase64String(d.AssignmentRowVersion);}protected void btnSubmit_Click(object s,EventArgs e){DefectCategory c;DefectSeverity v;var r=ServiceFactory.CreateDriverOperationsService().ReportDefect(new ReportDefectRequest{TripId=Id,Category=Enum.TryParse(ddlCategory.SelectedValue,out c)?c:(DefectCategory?)null,Severity=Enum.TryParse(ddlSeverity.SelectedValue,out v)?v:(DefectSeverity?)null,Description=txtDescription.Text,TripRowVersion=Parse(hidTripRv.Value),AssignmentRowVersion=Parse(hidAssignmentRv.Value)},CurrentPrincipalContext.UserAccountId);if(r.Succeeded){Response.Redirect(ResolveUrl("~/Driver/TripDetails.aspx?id="+Id),true);return;}litError.Text=Server.HtmlEncode(string.Join(" ",r.Errors.Select(x=>x.Message)));pnlError.Visible=true;LoadContext();}private static string Label(string x){return x=="EngineDrivetrain"?"Engine / drivetrain":x=="BodyInterior"?"Body / interior":x;}private static byte[] Parse(string x){try{return Convert.FromBase64String(x);}catch{return null;}}}}
